import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total_n = scanner.nextInt();
        int modulus = scanner.nextInt();

        if (total_n == 1) {
            System.out.println(0);
            return;
        }

        int[] sequence = {1};
        long total_value = 0;

        for (int i = 2; i <= total_n; i++) {
            int size = ((i - 1) * i) / 2 + 1;
            int[] new_sequence = new int[size];

            long[] cum_sum = new long[sequence.length + 1];
            for (int index = sequence.length - 1; index >= 0; index--) {
                cum_sum[index] = (cum_sum[index + 1] + sequence[index]) % modulus;
            }

            for (int w = 0; w < size; w++) {
                int left_bound = Math.max(0, w + 1 - i);
                int right_bound = Math.min(sequence.length - 1, w);
                long sum_left = cum_sum[left_bound];
                long sum_right = (right_bound + 1 < cum_sum.length) ? cum_sum[right_bound + 1] : 0;
                new_sequence[w] = (int)((sum_left - sum_right) % modulus);
                if (new_sequence[w] < 0) new_sequence[w] += modulus;
            }

            long[] e_array = new long[cum_sum.length];
            long[] f_array = new long[cum_sum.length];

            for (int w = 0; w < cum_sum.length - 1; w++) {
                e_array[w + 1] = (e_array[w] + cum_sum[w]) % modulus;
                f_array[w + 1] = (f_array[w] - (long)w * cum_sum[w]) % modulus;
                if (e_array[w + 1] < 0) e_array[w + 1] += modulus;
                if (f_array[w + 1] < 0) f_array[w + 1] += modulus;
            }

            int R_idx = sequence.length;
            long temp_b_value = 0;

            int start_jj = Math.max(0, sequence.length - i);
            for (int jj = start_jj; jj < sequence.length - 1; jj++) {
                int L_idx = jj + 2;
                long numerator1 = (e_array[R_idx] - e_array[L_idx]) % modulus;
                if (numerator1 < 0) numerator1 += modulus;
                long numerator2 = (f_array[R_idx] - f_array[L_idx]) % modulus;
                if (numerator2 < 0) numerator2 += modulus;
                long term = (((numerator1 * (i + 1 + jj)) % modulus) + numerator2) % modulus;
                long product = (term * sequence[jj]) % modulus;
                temp_b_value = (temp_b_value + product) % modulus;
            }

            int end_jj = sequence.length - i;
            for (int jj = 0; jj < end_jj; jj++) {
                int L_idx = jj + 2;
                int R_idx = i + jj;
                long numerator1 = (e_array[R_idx + 1] - e_array[L_idx]) % modulus;
                if (numerator1 < 0) numerator1 += modulus;
                long numerator2 = (f_array[R_idx + 1] - f_array[L_idx]) % modulus;
                if (numerator2 < 0) numerator2 += modulus;
                long term = (((numerator1 * (i + 1 + jj)) % modulus) + numerator2) % modulus;
                long product = (term * sequence[jj]) % modulus;
                temp_b_value = (temp_b_value + product) % modulus;
            }

            long perm = calcPerm(total_n, total_n - i, modulus);
            total_value = (total_value + (temp_b_value * perm) % modulus) % modulus;

            sequence = new_sequence;
        }

        System.out.println(total_value % modulus);
        scanner.close();
    }

    private static long calcPerm(int n, int k, int modulus) {
        long result = 1;
        for (int i = 0; i < k; i++) {
            result = (result * (n - i)) % modulus;
        }
        return result;
    }
}

